        private Preparation(RemoteAssignmentWorkspaces issuer,TaskStore.TeamRemoteContext context,TaskStore.TeamRemoteClaim claim,JSONObject actual){this.issuer=issuer;this.context=context;this.claim=claim;receipt=actual.toString();}
        public JSONObject view()throws Exception{return new JSONObject(receipt);}
