    public Preparation prepare(NativeHost host,String preparedOperation,RunControl original)throws Exception {
        TaskStore.TeamRemoteContext context=host.context();JSONObject scope=scope(host,context).put("arguments",new JSONObject());currentSelection(scope);TaskStore.TeamRemoteClaim claim=host.claim(TaskStore.TeamRemoteAction.PREPARE,preparedOperation,scope,original);
        if(!claim.canDispatch())return new Preparation(this,context,claim,claim.view());JSONObject input=wire(claim.view());JSONObject actual;
        try{if(RemoteProjectAssignments.full(input)){host.checkExecutionCurrent(context);try(AutoCloseable current=original.retainAuthorityCheck(()->host.checkExecutionCurrent(context))){actual=module.prepareProjectAssignment(input,host.originalProjectPackage(context),original,()->host.beforeDispatch(claim,original));}}else actual=module.prepareAssignmentWorkspace(input,()->host.beforeDispatch(claim,original));}catch(java.io.IOException unavailable){actual=notice(input,"unknown");}
        host.record(claim,actual);return new Preparation(this,context,claim,actual);
    }
    public Preparation restorePreparation(NativeHost host,String preparedOperation)throws Exception {
        TaskStore.TeamRemoteContext context=host.context();host.checkOriginalRead(context);TaskStore.TeamRemoteClaim claim=host.originalClaim(preparedOperation);JSONObject view=claim.view();if(!view.getString("action").equals("PREPARE"))throw new SecurityException("原操作不是prepare");JSONObject query=wire(view).put("_profileBinding",module.profileBindingHash(view.getJSONObject("scope").getString("profileId")));JSONObject actual=RemoteProjectAssignments.full(query)?module.reconcileProjectAssignment(query):module.reconcileAssignmentPreparation(query);host.record(claim,actual);return new Preparation(this,context,claim,actual);
    }
    /** Stop only the original full-package preparation. No job creation, directory deletion or refund. */
    public JSONObject cancelPreparation(NativeHost host,Preparation prepared,String preparedOperation,RunControl original)throws Exception {
        check(host,prepared);if(preparedOperation!=null)throw new SecurityException("准备停止仅为原native清理，不替换Runner已登记tool动作");if(!RemoteProjectAssignments.full(prepared.context.view()))throw new SecurityException("旧selected-file准备不扩大清理协议");JSONObject scope=new JSONObject(prepared.claim.view().getJSONObject("scope").toString()).put("arguments",new JSONObject()).put("preparationPreparedOperationId",prepared.claim.view().getString("preparedOperationId")).put("preparationContext",prepared.context.view());
        TaskStore.TeamRemoteClaim claim=host.claim(TaskStore.TeamRemoteAction.CANCEL,preparedOperation,scope,original);JSONObject input=wire(claim.view());input.put("operationId",prepared.claim.view().getString("operationId"));JSONObject actual;
        if(!claim.canDispatch())actual=module.reconcileProjectAssignment(input);else try{actual=module.cancelProjectPreparation(input,()->host.beforeDispatch(claim,original));}catch(java.io.IOException unavailable){actual=notice(input,"unknown");}
        host.record(claim,actual);return actual;
    }
    public Execution submit(NativeHost host,Preparation prepared,String prompt,String preparedOperation,RunControl original)throws Exception {
        check(host,prepared);if(!prepared.ready())throw new SecurityException("原prepare还没有独立物理副本证明，只能核对");JSONObject scope=scope(host,host.context()).put("preparationContext",prepared.context.view()).put("arguments",new JSONObject().put("prompt",prompt)).put("prompt",prompt).put("prepareOperationId",prepared.claim.view().getString("preparedOperationId")).put("preparation",prepared.view());currentSelection(scope);
        TaskStore.TeamRemoteClaim claim=host.claim(TaskStore.TeamRemoteAction.SUBMIT,preparedOperation,scope,original);Execution execution=new Execution(this,host.context(),claim);if(!claim.canDispatch())return execution;JSONObject input=wire(claim.view()),actual;
        try{actual=module.submitAssignmentJob(input,()->host.beforeDispatch(claim,original));}catch(java.io.IOException unavailable){actual=notice(input,"unknown");}
        host.record(claim,actual);return execution;
    }
    public Execution restoreExecution(NativeHost host,String originalPreparedOperation)throws Exception {TaskStore.TeamRemoteContext context=host.context();host.checkOriginalRead(context);TaskStore.TeamRemoteClaim claim=host.originalClaim(originalPreparedOperation);if(!claim.view().getString("action").equals("SUBMIT"))throw new SecurityException("原操作不是制作job");return new Execution(this,context,claim);}
    public JSONObject inspect(NativeHost host,Execution execution)throws Exception {
        check(host,execution);TaskStore.TeamRemoteClaim original=host.originalClaim(execution.context,execution.claim.view().getString("preparedOperationId"));JSONObject view=original.view(),input=wire(view).put("_profileBinding",module.profileBindingHash(view.getJSONObject("scope").getString("profileId"))),actual;
        if(view.optString("jobId").isEmpty())actual=module.handle("reconcileOperation",input.put("operationId",view.getString("jobOperationId")));
        else actual=module.handle("getJob",input.put("jobId",view.getString("jobId")).put("jobOperationId",view.getString("jobOperationId")));
        host.checkOriginalRead(execution.context);host.record(original,actual);return actual;
    }
    public JSONObject cancel(NativeHost host,Execution execution,String preparedOperation,RunControl original)throws Exception {
        check(host,execution);JSONObject scope=executionScope(host,execution).put("arguments",new JSONObject());TaskStore.TeamRemoteClaim claim=host.claim(TaskStore.TeamRemoteAction.CANCEL,preparedOperation,scope,original);if(!claim.canDispatch())return claim.view();JSONObject input=wire(claim.view());JSONObject actual;
        try{actual=module.cancelAssignmentJob(input,()->host.beforeDispatch(claim,original));}catch(java.io.IOException unavailable){actual=notice(input,"unknown");}host.record(claim,actual);return actual;
    }
    public Contribution freeze(NativeHost host,Execution execution,String preparedOperation,RunControl original)throws Exception {
        check(host,execution);JSONObject latest=inspect(host,execution);if(!latest.optString("status").matches("completed|failed|cancelled")||!latest.optBoolean("dispatchFenceFinal"))throw new SecurityException("原job尚未最终结算，不能冻结贡献");JSONObject scope=executionScope(host,execution).put("arguments",new JSONObject());TaskStore.TeamRemoteClaim claim=host.claim(TaskStore.TeamRemoteAction.FREEZE,preparedOperation,scope,original);if(!claim.canDispatch())return new Contribution(this,host.context(),execution,preparedOperation,claim.view());JSONObject input=wire(claim.view()),actual;
        try{actual=RemoteProjectAssignments.full(input)?module.captureProjectContribution(input,()->host.beforeDispatch(claim,original)):module.captureResultSnapshot(input,()->host.beforeDispatch(claim,original));}catch(java.io.IOException unavailable){actual=notice(input,"unknown");}host.record(claim,actual);JSONObject metadata=actual.optString("status").equals("completed")?validateContribution(actual,claim.view().getJSONObject("scope")):actual;return new Contribution(this,host.context(),execution,preparedOperation,metadata);
    }
    public Contribution restoreContribution(NativeHost host,Execution execution,String originalPreparedOperation)throws Exception {
        check(host,execution);TaskStore.TeamRemoteClaim claim=host.originalClaim(originalPreparedOperation);if(!claim.view().getString("action").equals("FREEZE"))throw new SecurityException("原操作不是贡献冻结");JSONObject query=wire(claim.view()).put("_profileBinding",module.profileBindingHash(claim.view().getJSONObject("scope").getString("profileId")));JSONObject actual=RemoteProjectAssignments.full(query)?module.reconcileProjectContribution(query):module.reconcileResultSnapshot(query);host.record(claim,actual);JSONObject value=actual.optString("status").equals("completed")?validateContribution(actual,claim.view().getJSONObject("scope")):actual;return new Contribution(this,host.context(),execution,originalPreparedOperation,value);
    }
    /** Returns only an original tool claim. C6 writes verified bytes to its own draft and records that real receipt. */
    public TaskStore.TeamRemoteClaim claimImport(NativeHost host,Contribution contribution,JSONObject nativeDraft,String preparedOperation,RunControl original)throws Exception {
        check(host,contribution);JSONObject manifest=contribution.view();if(!manifest.optString("status").equals("completed")||!manifest.has("assignmentContribution"))throw new SecurityException("没有原冻结贡献，不能导入手机草稿");JSONObject scope=executionScope(host,contribution.execution).put("arguments",new JSONObject()).put("contributionContext",contribution.context.view()).put("contributionPreparedOperationId",contribution.preparedOperation).put("contribution",manifest).put("manifestHash",TaskStore.capabilityFingerprint(manifest)).put("draft",new JSONObject(nativeDraft.toString()));return host.claim(TaskStore.TeamRemoteAction.IMPORT,preparedOperation,scope,original);
    }
    public ExactFile readExact(NativeHost host,Contribution contribution,String path)throws Exception {
        check(host,contribution);JSONObject frozen=contribution.view();JSONObject input=readQuery(contribution.context.view()).put("jobId",frozen.getString("jobId")).put("jobOperationId",frozen.getString("jobOperationId")).put("snapshotId",frozen.getString("snapshotId")).put("snapshotVersion",frozen.getString("snapshotVersion")).put("path",path);if(RemoteProjectAssignments.full(contribution.context.view())){JSONObject metadata=null;JSONArray files=frozen.getJSONArray("files");for(int i=0;i<files.length();i++)if(path.equals(files.getJSONObject(i).getString("path")))metadata=new JSONObject(files.getJSONObject(i).toString());if(metadata==null)throw new SecurityException("文件不在原native冻结项目贡献范围");if(metadata.optBoolean("tombstone"))return new ExactFile(metadata,null);byte[] raw=module.readProjectContributionFile(input,metadata,()->host.checkOriginalRead(contribution.context));host.checkOriginalRead(contribution.context);return new ExactFile(metadata,raw);}JSONObject actual=module.readResultSnapshot(input);JSONObject metadata=RemoteResultSnapshots.file(actual,frozen,path);host.checkOriginalRead(contribution.context);return new ExactFile(metadata,Base64.getDecoder().decode(actual.getString("base64")));
    }
    public static final class ExactFile implements AutoCloseable {
        private final String metadata;private final boolean tombstone;private byte[] bytes;private ExactFile(JSONObject metadata,byte[] bytes){this.metadata=metadata.toString();this.tombstone=metadata.optBoolean("tombstone");this.bytes=bytes;}
        public JSONObject view()throws Exception{return new JSONObject(metadata);}
        public synchronized byte[] copyBytes(){if(tombstone)throw new IllegalStateException("原删除证明没有文件正文，不能伪作空文件");if(bytes==null)throw new IllegalStateException("原文件已释放");return bytes.clone();}
        public synchronized void close(){if(bytes!=null)Arrays.fill(bytes,(byte)0);bytes=null;}
    }
    private JSONObject scope(NativeHost host,TaskStore.TeamRemoteContext context)throws Exception {host.checkOriginalRead(context);JSONObject value=context.view();if(RemoteProjectAssignments.full(value)){RemoteProjectAssignments.validateSelection(value);return value;}validateLimits(value.getJSONObject("limits"));JSONObject original=host.originalSnapshot(context);if(!value.getString("snapshotVersion").equals(original.getString("snapshotVersion")))throw new SecurityException("原快照版本改变");return value;}
    private JSONObject executionScope(NativeHost host,Execution execution)throws Exception {TaskStore.TeamRemoteClaim claim=host.originalClaim(execution.context,execution.claim.view().getString("preparedOperationId"));JSONObject view=claim.view(),original=view.getJSONObject("scope"),scope=scope(host,host.context());for(String key:new String[]{"preparation","assignmentWorkspace"})scope.put(key,original.get(key));for(String key:new String[]{"childTaskId","jobOperationId","jobId","reservationId"})if(view.has(key))scope.put(key,view.get(key));return scope.put("executionContext",execution.context.view()).put("executionPreparedOperationId",view.getString("preparedOperationId"));}
    private JSONObject readQuery(JSONObject view)throws Exception {return new JSONObject().put("profileId",view.getString("profileId")).put("_profileBinding",module.profileBindingHash(view.getString("profileId"))).put("serviceBase",view.getString("serviceBase"));}
    private static JSONObject wire(JSONObject claim)throws Exception {JSONObject scope=claim.getJSONObject("scope"),value=new JSONObject(scope.toString()).put("operationId",claim.getString("operationId")).put("_profileBinding",scope.getString("profileGeneration"));for(String key:new String[]{"approvalRevision","approvalExpiresAt","childTaskId","jobOperationId","jobId","reservationId"})if(claim.has(key))value.put(key,claim.get(key));if(scope.has("jobSource")){JSONObject source=scope.getJSONObject("jobSource");for(String key:new String[]{"jobId","jobOperationId","environmentId","worker","threadId","turnId","workspaceIdentity"})if(source.has(key))value.put(key,source.get(key));}JSONArray paths=new JSONArray(),files=scope.getJSONArray("files");for(int i=0;i<files.length();i++)paths.put(files.getJSONObject(i).getString("path"));return value.put("paths",paths);}
    private void currentSelection(JSONObject scope)throws Exception {module.requireProfileBinding(scope.getString("profileId"),scope.getString("profileGeneration"));JSONObject query=readQuery(scope);if(!scope.getString("environmentGeneration").equals(findEnvironment(module.handle("environments",query),scope.getString("environmentId")).getString("bindingHash")))throw new SecurityException("原远端环境generation已变化，必须重新原生审阅，不自动补预算");}
