    private static void sameScope(JSONObject current,JSONObject original)throws Exception {
        for(String key:new String[]{"ownerScopeId","ownerScopeRevision","profileId","profileGeneration","serviceBase","environmentId","environmentGeneration","files","limits","targetProjectId"})if(!canonical(current.get(key)).equals(canonical(original.get(key))))throw new SecurityException("新attempt不是原assignment已批scope");
        if(RemoteProjectAssignments.full(current)!=RemoteProjectAssignments.full(original))throw new SecurityException("制作模式已变化，旧job不能借权");for(String key:RemoteProjectAssignments.baseFields(current))if(!canonical(current.get(key)).equals(canonical(original.get(key))))throw new SecurityException("原项目/快照base已变化");
        for(String key:new String[]{"taskId","parentTaskId","parentRunId","parentEpoch","teamRunId","assignmentId","assignmentRevision","memberId"})if(!canonical(current.getJSONObject("nativeAssignment").get(key)).equals(canonical(original.getJSONObject("nativeAssignment").get(key))))throw new SecurityException("原制作改派/改版/换parent，旧成果只读");
        if(RemoteProjectAssignments.full(current))for(String key:new String[]{"workItemId","itemRevision","ownerGeneration"})if(!canonical(current.getJSONObject("nativeAssignment").get(key)).equals(canonical(original.getJSONObject("nativeAssignment").get(key))))throw new SecurityException("原项目工作项已换代");
    }
    public static JSONObject validatePreparation(JSONObject actual,JSONObject scope)throws Exception {
        if(RemoteProjectAssignments.full(scope))return RemoteProjectAssignments.preparation(actual,scope,true);
        for(String key:new String[]{"sourceJobId","environmentId","environmentBinding"})if(!scope.getString(key).equals(actual.optString(key)))throw new SecurityException("prepare来源不符: "+key);if(!scope.getString("operationId").equals(actual.optString("operationId"))||!scope.getString("snapshotId").equals(actual.optString("baseSnapshotId"))||!scope.getString("snapshotVersion").equals(actual.optString("baseSnapshotVersion"))||!canonical(scope.getJSONObject("nativeAssignment")).equals(canonical(actual.optJSONObject("nativeAssignment")))||!actual.optString("status").equals("ready")||!actual.optString("mode").equals("selected_file_copy_not_git_project")||!actual.optString("checkoutId").matches("[a-f0-9-]{36}")||!actual.optString("checkoutIdentity").matches("[a-f0-9]{64}")||!actual.optString("checkoutVersion").matches("[a-f0-9]{64}")||!Boolean.FALSE.equals(actual.opt("fullProject"))||!Boolean.FALSE.equals(actual.opt("osReadIsolationVerified")))throw new SecurityException("原物理所选文件副本proof不完整");
        JSONArray selected=scope.getJSONArray("files"),files=actual.getJSONArray("files");if(files.length()!=selected.length()||!canonical(actual.getJSONObject("limits")).equals(canonical(normalizedLimits(scope.getJSONObject("limits")))))throw new SecurityException("prepare路径/限制改变");for(int i=0;i<files.length();i++){JSONObject file=files.getJSONObject(i),base=selected.getJSONObject(i);if(!base.getString("path").equals(file.getString("path"))||!base.getString("baseHash").equals(file.getString("sha256"))||base.getInt("baseVersion")!=file.getInt("appBaseVersion"))throw new SecurityException("实际副本不是原项目base");}return new JSONObject(actual.toString());
    }
    public static JSONObject validateContribution(JSONObject actual,JSONObject scope)throws Exception {
        if(RemoteProjectAssignments.full(scope))return RemoteProjectAssignments.contribution(actual,scope);
        JSONObject source=scope.getJSONObject("jobSource"),copy=scope.getJSONObject("preparation"),reference=scope.getJSONObject("assignmentWorkspace"),proof=actual.getJSONObject("assignmentContribution");JSONArray paths=new JSONArray(),selected=scope.getJSONArray("files");for(int i=0;i<selected.length();i++)paths.put(selected.getJSONObject(i).getString("path"));JSONObject metadata=RemoteResultSnapshots.metadata(actual,source,scope.getString("operationId"),paths);
        if(!canonical(copy.getJSONObject("nativeAssignment")).equals(canonical(reference.getJSONObject("preparationNativeAssignment")))||!canonical(reference.getJSONObject("preparationNativeAssignment")).equals(canonical(proof.getJSONObject("preparationNativeAssignment"))))throw new SecurityException("原prepare物理tuple不能改写为新dispatch tuple");for(String key:new String[]{"checkoutId","checkoutVersion","checkoutIdentity","baseSnapshotId","baseSnapshotVersion"})if(!copy.getString(key).equals(proof.optString(key)))throw new SecurityException("贡献替换原checkout/base: "+key);if(!reference.getString("reservationId").equals(proof.optString("reservationId"))||!canonical(reference.getJSONObject("nativeAssignment")).equals(canonical(proof.optJSONObject("nativeAssignment")))||!proof.optString("source").equals("actual_selected_file_base_to_frozen_bytes")||!Boolean.FALSE.equals(proof.opt("integrated"))||!Boolean.FALSE.equals(proof.opt("independentlyReviewed"))||!Boolean.FALSE.equals(proof.opt("fullProject")))throw new SecurityException("原贡献来源/权限proof不符");
        JSONArray changes=proof.getJSONArray("files"),files=metadata.getJSONArray("files"),bases=copy.getJSONArray("files");if(changes.length()!=files.length())throw new SecurityException("贡献文件缺失");long bytes=metadata.getLong("bytes");for(int i=0;i<changes.length();i++){JSONObject change=changes.getJSONObject(i),file=files.getJSONObject(i),base=bases.getJSONObject(i);for(String key:new String[]{"path","sha256","fileVersion","bytes"})if(!canonical(file.get(key)).equals(canonical(change.get(key))))throw new SecurityException("真实贡献与冻结文件不符");if(!base.getString("sha256").equals(change.getString("baseSha256"))||!base.getString("fileVersion").equals(change.getString("baseFileVersion"))||base.getInt("appBaseVersion")!=change.getInt("appBaseVersion"))throw new SecurityException("贡献base不是原冻结副本");bytes=Math.addExact(bytes,change.getString("diff").getBytes(StandardCharsets.UTF_8).length);}if(bytes>scope.getJSONObject("limits").getLong("maxContributionBytes"))throw new SecurityException("真实贡献超出原批准输出cap");return metadata.put("assignmentContribution",new JSONObject(proof.toString())).put("contributionId",actual.getString("snapshotId"));
    }
    private static JSONObject normalizedLimits(JSONObject value)throws Exception {validateLimits(value);JSONObject result=new JSONObject();for(String key:new String[]{"maxWallTimeSeconds","maxOutputBytes","maxContributionBytes"})result.put(key,value.get(key));return result;}
    private static String canonical(Object value)throws Exception {if(value instanceof JSONObject){JSONObject object=(JSONObject)value;java.util.List<String> keys=new java.util.ArrayList<>();object.keys().forEachRemaining(keys::add);java.util.Collections.sort(keys);StringBuilder out=new StringBuilder("{");for(String key:keys){if(out.length()>1)out.append(',');out.append(JSONObject.quote(key)).append(':').append(canonical(object.get(key)));}return out.append('}').toString();}if(value instanceof JSONArray){JSONArray array=(JSONArray)value;StringBuilder out=new StringBuilder("[");for(int i=0;i<array.length();i++){if(i>0)out.append(',');out.append(canonical(array.get(i)));}return out.append(']').toString();}return value==JSONObject.NULL?"null":value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
